import subprocess,os,json,time,statistics,hashlib
from pathlib import Path
R=Path('/tmp/unisacc-memory-integrated');ROOT=Path('/Users/wjc/repos/unisacc');minimal=R/'minimal.c';minimal.write_text('int main(void){return 0;}\n')
variants={'single':(R/'frozen.com',False),'double':(R/'frozen.com',True),'plain_double':(R/'plain.com',True)}
def run(label,args):
 exe,double=variants[label];env=dict(os.environ);env.pop('UNISA_MEMORY_TWOPASS',None)
 if double:env['UNISA_MEMORY_TWOPASS']='1'
 start=time.perf_counter_ns();p=subprocess.run(['sh',str(exe),*map(str,args)],capture_output=True,timeout=12,env=env,cwd=ROOT)
 return (p.returncode,p.stdout,p.stderr),(time.perf_counter_ns()-start)/1e6
measure={}
for name,source in [('calc',ROOT/'examples/apps/calc.c'),('startup',minimal)]:
 expected=None;times={k:[] for k in variants}
 for k in variants:run(k,['-run',source])
 for i in range(5):
  keys=list(variants);keys=keys[i%3:]+keys[:i%3]
  for k in keys:
   value,ms=run(k,['-run',source]);assert value[0]==0 and not value[2],(k,value)
   if expected is None:expected=value
   assert value==expected,(k,name,value,expected)
   times[k].append(ms)
 measure[name]={'trials_ms':times,'median_ms':{k:statistics.median(v) for k,v in times.items()},'output_equal':True}
checks=[]
for source in ['examples/hello.c','examples/fib.c','examples/struct.c','tests/c/b_argv.c','tests/c/b_printf.c','tests/c/b_static.c','tests/c/b_funcptr.c','tests/c/b_strderef.c','examples/apps/calc.c','examples/apps/queens.c','examples/apps/life.c','examples/apps/wordfreq.c','examples/apps/bf.c','examples/apps/dijkstra.c']:
 for level in ('-O0','-O2'):
  vals=[run(k,[level,'-run',ROOT/source,'one','two'])[0] for k in variants];assert vals[0]==vals[1]==vals[2],(source,level,vals);checks.append({'source':source,'level':level,'rc':vals[0][0]})
images=[]
for target in ['lnx/arm64','lnx/x86_64','osx/arm64','osx/x86_64','win/arm64','win/x86_64']:
 vals=[run(k,['-O2','-b',target,ROOT/'examples/apps/calc.c'])[0] for k in ('single','plain_double')];assert vals[0]==vals[1] and vals[0][0]==0,(target,vals[0][:1],vals[1][:1]);images.append({'target':target,'bytes':len(vals[0][1]),'sha256':hashlib.sha256(vals[0][1]).hexdigest()})
result={'bench':measure,'checks':checks,'images':images,'artifacts':{k:{'bytes':exe.stat().st_size,'sha256':hashlib.sha256(exe.read_bytes()).hexdigest()} for k,(exe,_) in variants.items()}}
(R/'bench.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(measure,indent=2));print('behavior',len(checks),'native images',len(images))
